# ============================================================================
# Adaptive Rejection Sampling (Gilks & Wild, 1992)
# File: /app/ars.R
# ============================================================================

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
ARS_DEFAULT_N <- 10000
ARS_MAX_ITER  <- 1e6
ARS_TOL       <- 1e-10

# ---------------------------------------------------------------------------
# formula_to_function: Convert a one-sided formula to a callable function.
#   e.g., ~ dnorm(x, 0, 1)  ->  function(x) dnorm(x, 0, 1)
# ---------------------------------------------------------------------------
formula_to_function <- function(formula) {
  env <- environment(formula)
  body_expr <- formula[[3]]
  function(x) eval(body_expr, list(x = x), env)
}

# ---------------------------------------------------------------------------
# check_density_function: Validate and return a callable density function.
#   Accepts a function or a one-sided formula.
# ---------------------------------------------------------------------------
check_density_function <- function(density_function) {
  if (is.null(density_function))
    stop("Error: density_function is NULL. Provide a function or formula.", call. = FALSE)
  if (is.function(density_function)) return(density_function)
  if (is(density_function, "formula")) return(formula_to_function(density_function))
  stop("Error: density_function must be a function or a formula.", call. = FALSE)
}

# ---------------------------------------------------------------------------
# check_n: Validate the sample count.
# ---------------------------------------------------------------------------
check_n <- function(n) {
  if (missing(n)) return(ARS_DEFAULT_N)
  if (is.null(n) || length(n) != 1 || !is.numeric(n) || is.na(n) || n < 1 || n != as.integer(n))
    stop("Error: n must be a single positive integer.", call. = FALSE)
  as.integer(n)
}

# ---------------------------------------------------------------------------
# check_domain: Validate the domain bounds.
# ---------------------------------------------------------------------------
check_domain <- function(domain) {
  if (is.null(domain) || length(domain) != 2 || !is.numeric(domain) || any(is.na(domain)))
    stop("Error: domain must be a numeric vector of length 2.", call. = FALSE)
  if (domain[1] >= domain[2])
    stop("Error: domain[1] must be strictly less than domain[2].", call. = FALSE)
  domain
}

# ---------------------------------------------------------------------------
# numerical_derivative: Central (or one-sided) finite-difference derivative
#   of a scalar function f at point x.
# ---------------------------------------------------------------------------
numerical_derivative <- function(f, x, eps = 1e-7) {
  eps <- eps * max(1, abs(x))
  fp <- f(x + eps)
  fm <- f(x - eps)
  fx <- f(x)
  if (is.finite(fp) && is.finite(fm)) {
    (fp - fm) / (2 * eps)
  } else if (is.finite(fp)) {
    (fp - fx) / eps
  } else if (is.finite(fm)) {
    (fx - fm) / eps
  } else {
    stop("Error: cannot compute derivative at x.", call. = FALSE)
  }
}

# ---------------------------------------------------------------------------
# upper_hull_at: Evaluate the upper hull (lower envelope of tangent lines)
#   at point x, given support points z, log-density values h, and
#   derivative values hp.
# ---------------------------------------------------------------------------
upper_hull_at <- function(x, z, h, hp) {
  n_pts <- length(z)
  if (x <= z[1]) return(h[1] + hp[1] * (x - z[1]))
  if (x >= z[n_pts]) return(h[n_pts] + hp[n_pts] * (x - z[n_pts]))
  idx <- sum(z < x)
  t1 <- h[idx]   + hp[idx]   * (x - z[idx])
  t2 <- h[idx+1] + hp[idx+1] * (x - z[idx+1])
  min(t1, t2)
}
