# ---------------------------------------------------------------------------
# log_density_from_fn: Wrap a density function into a log-density function.
#   The user supplies a (possibly unnormalized) density, e.g. dnorm; we log it.
# ---------------------------------------------------------------------------
log_density_from_fn <- function(dfn) {
  function(x) {
    v <- as.numeric(dfn(x))
    if (any(is.na(v)))
      stop("Error: density function returned NA.", call. = FALSE)
    if (any(v < 0))
      stop("Error: density function returned a negative value.", call. = FALSE)
    log(v)   # log(0) == -Inf, acceptable in the tails
  }
}

# ---------------------------------------------------------------------------
# crossing_points: Interior breakpoints of the upper hull where consecutive
#   tangents meet. Also enforces log-concavity: for a log-concave density the
#   derivative must be non-increasing (denom >= 0) and each crossing point
#   must lie within its support interval.
# ---------------------------------------------------------------------------
crossing_points <- function(z, h, hp) {
  k <- length(z)
  if (k < 2) return(numeric(0))
  xbreaks <- numeric(k - 1)
  for (i in seq_len(k - 1)) {
    denom <- hp[i] - hp[i + 1]
    if (denom < -ARS_TOL) {
      stop("Error: density is not log-concave (derivative is increasing).", call. = FALSE)
    }
    if (abs(denom) < ARS_TOL) {
      xbreaks[i] <- (z[i] + z[i + 1]) / 2   # coincident tangents (linear region)
    } else {
      xbreaks[i] <- (hp[i] * z[i] - h[i] - hp[i + 1] * z[i + 1] + h[i + 1]) / denom
    }
    if (xbreaks[i] < z[i] - ARS_TOL || xbreaks[i] > z[i + 1] + ARS_TOL) {
      stop("Error: density is not log-concave (upper-hull crossing point out of range).", call. = FALSE)
    }
    xbreaks[i] <- min(max(xbreaks[i], z[i]), z[i + 1])
  }
  xbreaks
}

# ---------------------------------------------------------------------------
# segment_bounds: The [lo, hi] span of each of the k upper-hull segments.
# ---------------------------------------------------------------------------
segment_bounds <- function(z, xbreaks, domain) {
  k <- length(z)
  lo <- numeric(k); hi <- numeric(k)
  lo[1] <- domain[1]; hi[1] <- xbreaks[1]
  for (i in 2:(k - 1)) { lo[i] <- xbreaks[i - 1]; hi[i] <- xbreaks[i] }
  lo[k] <- xbreaks[k - 1]; hi[k] <- domain[2]
  list(lo = lo, hi = hi)
}

# ---------------------------------------------------------------------------
# segment_log_areas: Log of the integral of exp(line) over each segment, in a
#   numerically stable way. Line i is L_i(x) = m_i * x + c_i.
# ---------------------------------------------------------------------------
segment_log_areas <- function(z, h, hp, bounds) {
  k <- length(z)
  m <- hp
  cval <- h - hp * z
  logA <- numeric(k)
  for (i in seq_len(k)) {
    lo <- bounds$lo[i]; hi <- bounds$hi[i]
    a <- m[i] * lo + cval[i]
    b <- m[i] * hi + cval[i]
    if (m[i] > ARS_TOL) {
      logA[i] <- b - log(m[i]) + log1p(-exp(a - b))
    } else if (m[i] < -ARS_TOL) {
      logA[i] <- a - log(-m[i]) + log1p(-exp(b - a))
    } else {
      logA[i] <- a + log(hi - lo)
    }
  }
  logA
}

# ---------------------------------------------------------------------------
# sample_trunc_exp: Draw one value from exp(m*x + c) truncated to [lo, hi].
# ---------------------------------------------------------------------------
sample_trunc_exp <- function(m, cval, lo, hi) {
  u <- runif(1)
  if (abs(m) < ARS_TOL) return(lo + u * (hi - lo))
  a <- m * lo + cval
  b <- m * hi + cval
  if (is.infinite(lo) && lo < 0) {
    return((b + log(u) - cval) / m)
  }
  if (is.infinite(hi) && hi > 0) {
    return((a + log(1 - u) - cval) / m)
  }
  (a + log(1 + u * (exp(b - a) - 1)) - cval) / m
}

# ---------------------------------------------------------------------------
# sample_from_upper_hull: Draw a proposal from the normalized upper hull.
# ---------------------------------------------------------------------------
sample_from_upper_hull <- function(z, h, hp, bounds, logA, log_sum) {
  k <- length(z)
  p <- exp(logA - log_sum)
  seg <- sample.int(k, 1, prob = p)
  m <- hp[seg]; cval <- h[seg] - hp[seg] * z[seg]
  sample_trunc_exp(m, cval, bounds$lo[seg], bounds$hi[seg])
}

# ---------------------------------------------------------------------------
# lower_hull_at: Lower hull value at x (secant on interior, -Inf on tails).
# ---------------------------------------------------------------------------
lower_hull_at <- function(x, z, h, hp, domain) {
  k <- length(z)
  if (x <= z[1] || x >= z[k]) return(-Inf)
  idx <- sum(z < x)
  slope <- (h[idx + 1] - h[idx]) / (z[idx + 1] - z[idx])
  h[idx] + slope * (x - z[idx])
}

# ---------------------------------------------------------------------------
# insert_support: Add a new support point (x, hx, hpx), keep order, return list.
# ---------------------------------------------------------------------------
insert_support <- function(z, h, hp, x, hx, hpx) {
  z2 <- c(z, x); h2 <- c(h, hx); hp2 <- c(hp, hpx)
  ord <- order(z2)
  list(z = z2[ord], h = h2[ord], hp = hp2[ord])
}
