cat >> /app/ars.R << 'EOF'

# ---------------------------------------------------------------------------
# ars: Adaptive Rejection Sampler (Gilks & Wild, 1992)
#
# @param density_function  A vectorized function (or one-sided formula) that
#   returns the (possibly unnormalized) density for a numeric input x.
# @param domain  A numeric vector of length 2, c(lo, hi). May contain +/-Inf.
#   Must satisfy lo < hi.
# @param n  Number of samples to draw. Default 10000.
# @return  A numeric vector of length n containing the generated samples.
# ---------------------------------------------------------------------------
ars <- function(density_function, domain, n = ARS_DEFAULT_N) {
  # --- Input validation ---
  dfn  <- check_density_function(density_function)
  domain <- check_domain(domain)
  n    <- check_n(n)

  # --- Build log-density wrapper ---
  hfun <- log_density_from_fn(dfn)

  # --- Choose initial support points ---
  # For a proper ARS we need 2+ points. We pick the midpoint and a point
  # slightly to the right, or use user-provided points if domain is finite.
  lo <- domain[1]; hi <- domain[2]

  # Choose two initial points inside the domain
  z <- numeric(2)
  if (is.finite(lo) && is.finite(hi)) {
    z[1] <- lo + 0.4 * (hi - lo)
    z[2] <- lo + 0.6 * (hi - lo)
  } else if (!is.finite(lo) && is.finite(hi)) {
    z[1] <- hi - 1
    z[2] <- hi - 0.5
  } else if (is.finite(lo) && !is.finite(hi)) {
    z[1] <- lo + 0.5
    z[2] <- lo + 1
  } else {
    z[1] <- -1
    z[2] <- 1
  }

  # Evaluate h and hp at initial points
  h  <- sapply(z, hfun)
  if (any(!is.finite(h)))
    stop("Error: density function returned 0 or NA at initial support points. Try different domain.", call. = FALSE)
  hp <- sapply(z, function(x) numerical_derivative(hfun, x))

  # --- Main sampling loop ---
  samples <- numeric(n)
  i <- 0L          # sample counter
  iter <- 0L       # iteration counter

  while (i < n) {
    if (iter > ARS_MAX_ITER)
      stop("Error: ARS did not converge within maximum iterations.", call. = FALSE)
    iter <- iter + 1L

    # Compute upper-hull geometry
    xbreaks <- crossing_points(z, h, hp)
    bounds  <- segment_bounds(z, xbreaks, domain)
    logA    <- segment_log_areas(z, h, hp, bounds)
    log_sum <- max(logA) + log(sum(exp(logA - max(logA))))

    # Draw a proposal from the upper hull
    x_star <- sample_from_upper_hull(z, h, hp, bounds, logA, log_sum)

    # --- Log-concavity check: proposal must lie in [domain[1], domain[2]] ---
    if (x_star < domain[1] || x_star > domain[2]) {
      next
    }

    # Squeezing test (lower hull)
    h_lower <- lower_hull_at(x_star, z, h, hp, domain)
    if (is.finite(h_lower)) {
      u1 <- runif(1)
      if (log(u1) <= h_lower - upper_hull_at(x_star, z, h, hp)) {
        i <- i + 1L
        samples[i] <- x_star
        next
      }
    }

    # Rejection test (upper hull)
    h_star <- hfun(x_star)
    if (!is.finite(h_star)) next
    u1 <- runif(1)
    if (log(u1) <= h_star - upper_hull_at(x_star, z, h, hp)) {
      i <- i + 1L
      samples[i] <- x_star
    }

    # --- Adaptive update: add x_star as a new support point ---
    # Only add if it is strictly between existing points (and not a duplicate)
    if (x_star > z[1] && x_star < z[length(z)]) {
      # Check for near-duplicates
      if (all(abs(x_star - z) > 1e-10)) {
        hpx_star <- numerical_derivative(hfun, x_star)
        updated <- insert_support(z, h, hp, x_star, h_star, hpx_star)
        z <- updated$z; h <- updated$h; hp <- updated$hp
      }
    } else if (x_star > z[length(z)]) {
      # Add to the right (only if domain allows)
      if (is.finite(hi) && x_star < hi) {
        hpx_star <- numerical_derivative(hfun, x_star)
        updated <- insert_support(z, h, hp, x_star, h_star, hpx_star)
        z <- updated$z; h <- updated$h; hp <- updated$hp
      }
    } else if (x_star < z[1]) {
      # Add to the left
      if (is.finite(lo) && x_star > lo) {
        hpx_star <- numerical_derivative(hfun, x_star)
        updated <- insert_support(z, h, hp, x_star, h_star, hpx_star)
        z <- updated$z; h <- updated$h; hp <- updated$hp
      }
    }
  }

  return(samples)
}
