# ---------------------------------------------------------------------------
# run_test: Helper that runs a single test, captures results, and prints a
#   PASS/FAIL line with summary statistics. Returns TRUE if the test passed.
#
# @param name  Human-readable test name.
# @param samples  The numeric sample vector to examine.
# @param true_mean  The known population mean.
# @param true_sd  The known population standard deviation.
# @param tol  Absolute tolerance for |sample_mean - true_mean| (default 0.05).
# @param sd_tol  Absolute tolerance for |sample_sd - true_sd| (default 0.05).
# @param domain  The support the samples must lie in (default NULL = no check).
# ---------------------------------------------------------------------------
run_test <- function(name, samples, true_mean, true_sd,
                     tol = 0.05, sd_tol = 0.05, domain = NULL) {
  s_mean <- mean(samples)
  s_sd   <- sd(samples)
  n      <- length(samples)

  pass <- isTRUE(abs(s_mean - true_mean) <= tol) &&
          isTRUE(abs(s_sd - true_sd) <= sd_tol)

  if (!is.null(domain)) {
    pass <- pass && all(samples >= domain[1]) && all(samples <= domain[2])
  }

  status <- if (pass) "PASS" else "FAIL"
  cat(sprintf("%s: %s | n=%d  mean=%.4f (expected %.4f, |diff|=%.4f)  sd=%.4f (expected %.4f, |diff|=%.4f)\n",
              name, status, n, s_mean, true_mean, abs(s_mean - true_mean),
              s_sd, true_sd, abs(s_sd - true_sd)))
  pass
}

# ---------------------------------------------------------------------------
# test: Run the full formal test suite and write sample files.
#
# Each test draws samples from a known log-concave distribution via ars(),
# compares the sample mean and sd to the known population values, and prints
# a PASS/FAIL line. It also writes sample files to /app/.
# ---------------------------------------------------------------------------
test <- function() {
  cat("=== ARS Formal Test Suite ===\n\n")
  set.seed(42)
  n_samples <- 20000
  results <- list()

  # --- Test 1: Standard Normal N(0, 1) ---
  cat("Test 1: Standard Normal N(0, 1)\n")
  normal_samples <- try(ars(dnorm, c(-Inf, Inf), n_samples), silent = TRUE)
  if (inherits(normal_samples, "try-error")) {
    cat("TEST_NORMAL: FAIL | ars() raised an error:\n")
    print(attr(normal_samples, "condition"))
    results[["normal"]] <- FALSE
  } else {
    results[["normal"]] <- run_test("TEST_NORMAL", normal_samples, 0, 1,
                                     tol = 0.05, sd_tol = 0.05)
  }

  # --- Test 2: Normal N(3, 2^2) ---
  cat("\nTest 2: Normal N(3, 2^2)\n")
  n32_samples <- try(ars(function(x) dnorm(x, 3, 2), c(-Inf, Inf), n_samples), silent = TRUE)
  if (inherits(n32_samples, "try-error")) {
    cat("TEST_NORMAL_3_2: FAIL | ars() raised an error:\n")
    print(attr(n32_samples, "condition"))
    results[["normal_3_2"]] <- FALSE
  } else {
    results[["normal_3_2"]] <- run_test("TEST_NORMAL_3_2", n32_samples, 3, 2,
                                         tol = 0.05, sd_tol = 0.05)
  }

  # --- Test 3: Exponential(1) on [0, Inf) ---
  cat("\nTest 3: Exponential(1) on [0, Inf)\n")
  exp_samples <- try(ars(dexp, c(0, Inf), n_samples), silent = TRUE)
  if (inherits(exp_samples, "try-error")) {
    cat("TEST_EXPONENTIAL: FAIL | ars() raised an error:\n")
    print(attr(exp_samples, "condition"))
    results[["exponential"]] <- FALSE
  } else {
    results[["exponential"]] <- run_test("TEST_EXPONENTIAL", exp_samples, 1, 1,
                                          tol = 0.05, sd_tol = 0.05,
                                          domain = c(0, Inf))
  }

  # --- Test 4: Gamma(5, 1) on [0, Inf) (log-concave for shape >= 1) ---
  cat("\nTest 4: Gamma(shape=5, rate=1) on [0, Inf)\n")
  gamma_samples <- try(ars(dgamma, c(0, Inf), n_samples), silent = TRUE)
  if (inherits(gamma_samples, "try-error")) {
    cat("TEST_GAMMA: FAIL | ars() raised an error:\n")
    print(attr(gamma_samples, "condition"))
    results[["gamma"]] <- FALSE
  } else {
    results[["gamma"]] <- run_test("TEST_GAMMA", gamma_samples, 5, sqrt(5),
                                    tol = 0.1, sd_tol = 0.1, domain = c(0, Inf))
  }

  # --- Test 5: Beta(2, 3) on [0, 1] (log-concave) ---
  cat("\nTest 5: Beta(2, 3) on [0, 1]\n")
  beta_samples <- try(ars(dbeta, c(0, 1), n_samples), silent = TRUE)
  if (inherits(beta_samples, "try-error")) {
    cat("TEST_BETA: FAIL | ars() raised an error:\n")
    print(attr(beta_samples, "condition"))
    results[["beta"]] <- FALSE
  } else {
    results[["beta"]] <- run_test("TEST_BETA", beta_samples, 2/5, sqrt(6/175),
                                   tol = 0.05, sd_tol = 0.05, domain = c(0, 1))
  }

  # --- Test 6: Log-normal via exp(dnorm) is NOT log-concave -> should error ---
  cat("\nTest 6: Log-normal (not log-concave) should raise an error\n")
  lognormal_err <- try(ars(function(x) dnorm(log(x), 0, 1), c(0.1, 10), 1000), silent = TRUE)
  if (inherits(lognormal_err, "try-error")) {
    err_msg <- attr(lognormal_err, "condition")$message
    if (grepl("not log-concave", err_msg, ignore.case = TRUE)) {
      cat("TEST_NONLOGCONCAVE: PASS | Correctly detected non-log-concave density\n")
      results[["nonlogconcave"]] <- TRUE
    } else {
      cat("TEST_NONLOGCONCAVE: FAIL | Error raised but not about log-concavity:\n")
      cat(err_msg, "\n")
      results[["nonlogconcave"]] <- FALSE
    }
  } else {
    cat("TEST_NONLOGCONCAVE: FAIL | Expected an error but none was raised\n")
    results[["nonlogconcave"]] <- FALSE
  }

  # --- Test 7: Input validation - negative n ---
  cat("\nTest 7: Input validation - negative n should raise an error\n")
  neg_n_err <- try(ars(dnorm, c(-Inf, Inf), -5), silent = TRUE)
  if (inherits(neg_n_err, "try-error")) {
    cat("TEST_VALIDATION_NEG_N: PASS | Correctly rejected negative n\n")
    results[["validation_neg_n"]] <- TRUE
  } else {
    cat("TEST_VALIDATION_NEG_N: FAIL | Expected error for negative n\n")
    results[["validation_neg_n"]] <- FALSE
  }

  # --- Test 8: Input validation - invalid domain ---
  cat("\nTest 8: Input validation - invalid domain should raise an error\n")
  bad_domain_err <- try(ars(dnorm, c(5, -5), 1000), silent = TRUE)
  if (inherits(bad_domain_err, "try-error")) {
    cat("TEST_VALIDATION_DOMAIN: PASS | Correctly rejected invalid domain\n")
    results[["validation_domain"]] <- TRUE
  } else {
    cat("TEST_VALIDATION_DOMAIN: FAIL | Expected error for invalid domain\n")
    results[["validation_domain"]] <- FALSE
  }

  # --- Write sample files ---
  cat("\n--- Writing sample files ---\n")
  if (!inherits(normal_samples, "try-error")) {
    write.table(normal_samples, file = "/app/normal_samples.txt",
                row.names = FALSE, col.names = FALSE, quote = FALSE)
    cat("Wrote /app/normal_samples.txt (", n_samples, " samples)\n", sep = "")
  }
  if (!inherits(exp_samples, "try-error")) {
    write.table(exp_samples, file = "/app/exponential_samples.txt",
                row.names = FALSE, col.names = FALSE, quote = FALSE)
    cat("Wrote /app/exponential_samples.txt (", n_samples, " samples)\n", sep = "")
  }

  # --- Summary ---
  cat("\n=== Summary ===\n")
  for (nm in names(results)) {
    status <- if (results[[nm]]) "PASS" else "FAIL"
    cat(sprintf("  %s: %s\n", nm, status))
  }
  n_pass <- sum(unlist(results))
  cat(sprintf("\nTotal: %d/%d tests passed\n", n_pass, length(results)))

  invisible(results)
}
EOF

